ALTER TABLE public.reader_bingos ADD COLUMN source_credit text NOT NULL DEFAULT '' CHECK(length(source_credit)<=1200);
ALTER TABLE public.books ADD COLUMN private_cover_path text CHECK(private_cover_path IS NULL OR private_cover_path LIKE user_id::text||'/book-cover/'||id::text||'/%');
CREATE TABLE public.reader_day_rewards(user_id uuid NOT NULL, day date NOT NULL, decoration text NOT NULL CHECK(decoration IN ('fern','lamp','books','moon')), equipped boolean NOT NULL DEFAULT false, slot integer NOT NULL DEFAULT 0 CHECK(slot BETWEEN 0 AND 3), PRIMARY KEY(user_id,day));
GRANT SELECT ON public.reader_day_rewards TO authenticated; GRANT ALL ON public.reader_day_rewards TO service_role;
ALTER TABLE public.reader_day_rewards ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_day_rewards ON public.reader_day_rewards FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.reader_claim_rewards() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE n integer;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.';END IF;INSERT INTO public.reader_day_rewards(user_id,day,decoration) SELECT auth.uid(),d, (ARRAY['fern','lamp','books','moon'])[1+mod(abs(d-date '2000-01-01'),4)] FROM (SELECT s.day d FROM public.reading_sessions s JOIN public.books b ON b.id=s.book_id WHERE b.user_id=auth.uid() AND s.to_page>s.from_page UNION SELECT c.streak_day FROM public.completed_readings c JOIN public.books b ON b.id=c.book_id WHERE b.user_id=auth.uid() AND c.streak_day IS NOT NULL) days ON CONFLICT DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;RETURN n;END$$;
CREATE FUNCTION public.reader_equip_reward(p_day date,p_slot integer,p_equipped boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF auth.uid() IS NULL OR p_slot NOT BETWEEN 0 AND 3 THEN RAISE EXCEPTION 'Selección inválida.';END IF;PERFORM 1 FROM public.reader_day_rewards WHERE user_id=auth.uid() FOR UPDATE;IF NOT EXISTS(SELECT 1 FROM public.reader_day_rewards WHERE user_id=auth.uid() AND day=p_day) THEN RAISE EXCEPTION 'Objeto no disponible.';END IF;IF p_equipped THEN UPDATE public.reader_day_rewards SET equipped=false WHERE user_id=auth.uid() AND slot=p_slot;END IF;UPDATE public.reader_day_rewards SET equipped=p_equipped,slot=p_slot WHERE user_id=auth.uid() AND day=p_day;END$$;
REVOKE ALL ON FUNCTION public.reader_claim_rewards(),public.reader_equip_reward(date,integer,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reader_claim_rewards(),public.reader_equip_reward(date,integer,boolean) TO authenticated;
CREATE POLICY private_book_cover_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='reader-profile-media' AND EXISTS(SELECT 1 FROM public.books b WHERE name LIKE b.user_id::text||'/book-cover/'||b.id::text||'/%' AND b.user_id=auth.uid()) AND lower(storage.extension(name))='webp' AND metadata->>'mimetype'='image/webp' AND (metadata->>'size')::bigint BETWEEN 1 AND 5242880);
CREATE TABLE public.reader_joint_intervals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reading_id uuid NOT NULL REFERENCES public.reader_joint_readings ON DELETE CASCADE,user_id uuid NOT NULL,book_id uuid NOT NULL REFERENCES public.books ON DELETE CASCADE,starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz,CHECK(ends_at IS NULL OR ends_at>=starts_at));
GRANT SELECT ON public.reader_joint_intervals TO authenticated;GRANT ALL ON public.reader_joint_intervals TO service_role;
ALTER TABLE public.reader_joint_intervals ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_joint_intervals ON public.reader_joint_intervals FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE UNIQUE INDEX one_open_joint_interval ON public.reader_joint_intervals(reading_id,user_id) WHERE ends_at IS NULL;
INSERT INTO public.reader_joint_intervals(reading_id,user_id,book_id,starts_at,ends_at) SELECT reading_id,user_id,book_id,joined_at,left_at FROM public.reader_joint_participants;
CREATE FUNCTION public.reader_track_joint_interval() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.reader_joint_intervals(reading_id,user_id,book_id,starts_at,ends_at) VALUES(NEW.reading_id,NEW.user_id,NEW.book_id,NEW.joined_at,NEW.left_at);ELSIF OLD.left_at IS NULL AND NEW.left_at IS NOT NULL THEN UPDATE public.reader_joint_intervals SET ends_at=NEW.left_at WHERE reading_id=NEW.reading_id AND user_id=NEW.user_id AND ends_at IS NULL;ELSIF OLD.left_at IS NOT NULL AND NEW.left_at IS NULL THEN INSERT INTO public.reader_joint_intervals(reading_id,user_id,book_id) VALUES(NEW.reading_id,NEW.user_id,NEW.book_id);END IF;RETURN NEW;END$$;
CREATE TRIGGER joint_interval_tracking AFTER INSERT OR UPDATE ON public.reader_joint_participants FOR EACH ROW EXECUTE FUNCTION public.reader_track_joint_interval();
CREATE FUNCTION public.reader_joint_days(p_reading uuid) RETURNS TABLE(user_id uuid,day date) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT DISTINCT i.user_id,s.day FROM public.reader_joint_intervals i JOIN public.reading_sessions s ON s.book_id=i.book_id WHERE i.reading_id=p_reading AND s.to_page>s.from_page AND s.created_at>=i.starts_at AND (i.ends_at IS NULL OR s.created_at<=i.ends_at) UNION SELECT i.user_id,c.streak_day FROM public.reader_joint_intervals i JOIN public.completed_readings c ON c.book_id=i.book_id WHERE i.reading_id=p_reading AND c.streak_day IS NOT NULL AND c.finished_at>=i.starts_at AND (i.ends_at IS NULL OR c.finished_at<=i.ends_at)$$;
REVOKE ALL ON FUNCTION public.reader_joint_days(uuid),public.reader_track_joint_interval() FROM PUBLIC,authenticated,anon;
ALTER TABLE public.reader_joint_participants ADD COLUMN chapter_ends integer[] NOT NULL DEFAULT '{}';
CREATE FUNCTION public.reader_set_chapter_ends(p_reading uuid,p_ends integer[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE p public.reader_joint_participants;b public.books;r public.reader_joint_readings;BEGIN SELECT * INTO STRICT p FROM public.reader_joint_participants WHERE reading_id=p_reading AND user_id=auth.uid() AND left_at IS NULL;SELECT * INTO STRICT b FROM public.books WHERE id=p.book_id AND user_id=auth.uid();SELECT * INTO STRICT r FROM public.reader_joint_readings WHERE id=p_reading;IF NOT public.reader_club_member(r.club_id,auth.uid()) OR cardinality(p_ends)<>r.chapters OR b.pages<=0 OR p_ends[cardinality(p_ends)]>b.pages OR EXISTS(SELECT 1 FROM unnest(p_ends) WITH ORDINALITY e(v,n) WHERE v IS NULL OR v<=0 OR (n>1 AND v<=p_ends[n::integer-1])) THEN RAISE EXCEPTION 'Indica las páginas finales reales, crecientes, de todos los capítulos de tu edición.';END IF;UPDATE public.reader_joint_participants SET chapter_ends=p_ends WHERE reading_id=p_reading AND user_id=auth.uid();END$$;
CREATE OR REPLACE FUNCTION public.reader_chapter_access(p_reading uuid,p_chapter integer) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(p_chapter BETWEEN 1 AND r.chapters AND cardinality(p.chapter_ends)=r.chapters AND b.current_page>=p.chapter_ends[p_chapter],false) FROM public.reader_joint_readings r JOIN public.reader_joint_participants p ON p.reading_id=r.id AND p.user_id=auth.uid() AND p.left_at IS NULL JOIN public.books b ON b.id=p.book_id AND b.user_id=p.user_id WHERE r.id=p_reading AND public.reader_club_member(r.club_id,auth.uid())$$;
REVOKE ALL ON FUNCTION public.reader_set_chapter_ends(uuid,integer[]) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.reader_set_chapter_ends(uuid,integer[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.reader_joint_summary(p_reading uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE r public.reader_joint_readings;zone text;days date[];streak integer:=0;cursor_day date;people jsonb;BEGIN SELECT * INTO STRICT r FROM public.reader_joint_readings WHERE id=p_reading;IF NOT public.reader_club_member(r.club_id,auth.uid()) THEN RAISE EXCEPTION 'No perteneces al club.';END IF;SELECT timezone INTO zone FROM public.reader_clubs WHERE id=r.club_id;SELECT array_agg(DISTINCT day) INTO days FROM public.reader_joint_days(r.id);cursor_day:=(now() AT TIME ZONE zone)::date;IF NOT cursor_day=ANY(coalesce(days,'{}'::date[])) THEN cursor_day:=cursor_day-1;END IF;WHILE cursor_day=ANY(coalesce(days,'{}'::date[])) LOOP streak:=streak+1;cursor_day:=cursor_day-1;END LOOP;SELECT coalesce(jsonb_agg(jsonb_build_object('handle',coalesce(sp.handle,'lector'),'percent',public.reader_joint_percent(r.id,p.user_id),'days',(SELECT count(DISTINCT day) FROM public.reader_joint_days(r.id) e WHERE e.user_id=p.user_id))),'[]'::jsonb) INTO people FROM public.reader_joint_participants p LEFT JOIN public.reader_social_profiles sp ON sp.user_id=p.user_id AND public.reader_can_view(sp.user_id,sp.visibility,sp.club_id) WHERE p.reading_id=r.id AND p.left_at IS NULL AND public.reader_club_member(r.club_id,p.user_id) AND NOT public.reader_blocked(p.user_id,auth.uid());RETURN jsonb_build_object('streak',streak,'participants',people,'my_percent',coalesce(public.reader_joint_percent(r.id,auth.uid()),0));END$$;
CREATE FUNCTION public.reader_preview_allows(p_owner uuid,p_visibility text,p_club uuid,p_viewer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT NOT public.reader_blocked(p_owner,p_viewer) AND (p_visibility='public' OR (p_visibility='friends' AND EXISTS(SELECT 1 FROM public.reader_friendships WHERE state='accepted' AND ((requester=p_owner AND recipient=p_viewer) OR (recipient=p_owner AND requester=p_viewer)))) OR (p_visibility='club' AND public.reader_club_member(p_club,p_owner) AND public.reader_club_member(p_club,p_viewer)))$$;
REVOKE ALL ON FUNCTION public.reader_preview_allows(uuid,text,uuid,uuid) FROM PUBLIC,authenticated,anon;
CREATE FUNCTION public.reader_preview(p_mode text,p_handle text DEFAULT '',p_club uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE viewer uuid;profile public.reader_social_profiles;contents jsonb;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.';END IF;SELECT * INTO STRICT profile FROM public.reader_social_profiles WHERE user_id=auth.uid();IF p_mode='friend' THEN SELECT user_id INTO STRICT viewer FROM public.reader_social_profiles WHERE handle=lower(trim(leading '@' FROM p_handle));IF NOT EXISTS(SELECT 1 FROM public.reader_friendships WHERE state='accepted' AND ((requester=auth.uid() AND recipient=viewer) OR (recipient=auth.uid() AND requester=viewer))) THEN RAISE EXCEPTION 'Elige una amistad aceptada.';END IF;ELSIF p_mode='club' THEN SELECT user_id INTO STRICT viewer FROM public.reader_social_profiles WHERE handle=lower(trim(leading '@' FROM p_handle));IF viewer=auth.uid() OR NOT public.reader_club_member(p_club,auth.uid()) OR NOT public.reader_club_member(p_club,viewer) THEN RAISE EXCEPTION 'Elige otro integrante de tu club.';END IF;ELSIF p_mode<>'public' THEN RAISE EXCEPTION 'Vista inválida.';END IF;IF NOT public.reader_preview_allows(auth.uid(),profile.visibility,profile.club_id,viewer) THEN RETURN jsonb_build_object('profile',NULL,'contents','[]'::jsonb);END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('kind',s.kind,'title',CASE WHEN s.kind IN ('book','rating') THEN (SELECT title FROM public.books WHERE id=s.source_id AND user_id=auth.uid()) WHEN s.kind='list' THEN (SELECT name FROM public.reader_lists WHERE id=s.source_id AND user_id=auth.uid()) ELSE (SELECT title FROM public.reader_bingos WHERE id=s.source_id AND user_id=auth.uid()) END)) FILTER(WHERE public.reader_preview_allows(auth.uid(),s.visibility,s.club_id,viewer)),'[]'::jsonb) INTO contents FROM public.reader_shares s WHERE s.user_id=auth.uid();RETURN jsonb_build_object('profile',jsonb_build_object('handle',profile.handle,'name',profile.name,'bio',profile.bio),'contents',contents);END$$;
REVOKE ALL ON FUNCTION public.reader_preview(text,text,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.reader_preview(text,text,uuid) TO authenticated;